const listOrders = `-- name: ListOrders :many
SELECT tenant_id, id, number, status, customer_user_id, customer_name, customer_email, shipping_address, shipping_method, shipping_amount, subtotal_amount, discount_amount, tax_amount, total_amount, currency, tracking_code, cancel_reason, payment_due_at, version, created_at, updated_at, store_host
FROM orders.orders o
WHERE o.tenant_id = $1
  AND ($2::text IS NULL OR o.status = $2)
  AND ($3::uuid IS NULL OR o.customer_user_id = $3)
  AND ($4::text IS NULL
       OR o.customer_email ILIKE '%' || $4 || '%'
       OR o.number::text = $4)
  AND ($5::timestamptz IS NULL
       OR (o.created_at, o.id) < ($5::timestamptz, $6::uuid))
ORDER BY o.created_at DESC, o.id DESC
LIMIT $7
`

type ListOrdersParams struct {
	TenantID       uuid.UUID
	Status         *string
	CustomerUserID *uuid.UUID
	Search         *string
	AfterAt        *time.Time
	AfterID        *uuid.UUID
	RowLimit       int32
}

func (q *Queries) ListOrders(ctx context.Context, arg ListOrdersParams) ([]OrdersOrder, error) {
	rows, err := q.db.Query(ctx, listOrders,
		arg.TenantID,
		arg.Status,
		arg.CustomerUserID,
		arg.Search,
		arg.AfterAt,
		arg.AfterID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OrdersOrder
	for rows.Next() {
		var i OrdersOrder
		if err := rows.Scan(
			&i.TenantID,
			&i.ID,
			&i.Number,
			&i.Status,
			&i.CustomerUserID,
			&i.CustomerName,
			&i.CustomerEmail,
			&i.ShippingAddress,
			&i.ShippingMethod,
			&i.ShippingAmount,
			&i.SubtotalAmount,
			&i.DiscountAmount,
			&i.TaxAmount,
			&i.TotalAmount,
			&i.Currency,
			&i.TrackingCode,
			&i.CancelReason,
			&i.PaymentDueAt,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.StoreHost,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

